-- Pickup and packing workflow, masters, tracked packages, financial entries, and materials.
SET XACT_ABORT ON; BEGIN TRANSACTION;
CREATE TABLE [dbo].[PickupStatuses]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[Code] NVARCHAR(40) NOT NULL,[Name] NVARCHAR(120) NOT NULL,[DisplayOrder] INT NOT NULL,[Color] NVARCHAR(30),[IsCompleted] BIT NOT NULL,[IsActive] BIT NOT NULL,UNIQUE([TenantId],[Code]));
CREATE TABLE [dbo].[Vehicles]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[RegistrationNumber] NVARCHAR(40) NOT NULL,[Name] NVARCHAR(120) NOT NULL,[Type] NVARCHAR(80) NOT NULL,[CapacityCbm] DECIMAL(12,3) NOT NULL,[DriverName] NVARCHAR(120),[DriverPhone] NVARCHAR(40),[IsActive] BIT NOT NULL,UNIQUE([TenantId],[RegistrationNumber]));
CREATE TABLE [dbo].[Pickups]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[PickupNumber] NVARCHAR(40) NOT NULL,[QuotationId] UNIQUEIDENTIFIER NULL REFERENCES [dbo].[Quotations]([Id]),[CustomerName] NVARCHAR(160) NOT NULL,[Phone] NVARCHAR(40) NOT NULL,[Email] NVARCHAR(254),[Address] NVARCHAR(500) NOT NULL,[Latitude] DECIMAL(10,7),[Longitude] DECIMAL(10,7),[ScheduledAtUtc] DATETIMEOFFSET NOT NULL,[ConfirmedAtUtc] DATETIMEOFFSET,[StatusId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[PickupStatuses]([Id]),[VehicleId] UNIQUEIDENTIFIER NULL REFERENCES [dbo].[Vehicles]([Id]),[Notes] NVARCHAR(2000),[ConfirmationTokenHash] NVARCHAR(64),[ConfirmationExpiresAtUtc] DATETIMEOFFSET,[CreatedAtUtc] DATETIMEOFFSET NOT NULL,[UpdatedAtUtc] DATETIMEOFFSET NOT NULL,UNIQUE([TenantId],[PickupNumber]));
CREATE UNIQUE INDEX [IX_Pickups_ConfirmationTokenHash] ON [dbo].[Pickups]([ConfirmationTokenHash]) WHERE [ConfirmationTokenHash] IS NOT NULL;
CREATE TABLE [dbo].[PickupAssignments]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[PickupId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Pickups]([Id]) ON DELETE CASCADE,[EmployeeId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Employees]([Id]),[Role] NVARCHAR(80) NOT NULL);
CREATE TABLE [dbo].[PickupPackages]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[PickupId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Pickups]([Id]) ON DELETE CASCADE,[BoxTypeId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[BoxTypes]([Id]),[TrackingNumber] NVARCHAR(80) NOT NULL,[Notes] NVARCHAR(500),UNIQUE([TenantId],[TrackingNumber]));
CREATE TABLE [dbo].[PickupPackageItems]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[PickupPackageId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[PickupPackages]([Id]) ON DELETE CASCADE,[ItemName] NVARCHAR(160) NOT NULL,[Quantity] INT NOT NULL,[Notes] NVARCHAR(500));
CREATE TABLE [dbo].[PickupMaterialUsages]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[PickupId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Pickups]([Id]) ON DELETE CASCADE,[MaterialId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[PackingMaterials]([Id]),[Quantity] DECIMAL(12,3) NOT NULL,[UnitCost] DECIMAL(18,2) NOT NULL);
CREATE TABLE [dbo].[PickupTransactions]([SerialNo] INT IDENTITY PRIMARY KEY,[Id] UNIQUEIDENTIFIER NOT NULL UNIQUE,[TenantId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Tenants]([Id]),[PickupId] UNIQUEIDENTIFIER NOT NULL REFERENCES [dbo].[Pickups]([Id]) ON DELETE CASCADE,[TransactionNumber] NVARCHAR(60) NOT NULL,[Type] NVARCHAR(20) NOT NULL,[Category] NVARCHAR(120) NOT NULL,[Amount] DECIMAL(18,2) NOT NULL,[PaymentMethod] NVARCHAR(40) NOT NULL,[Notes] NVARCHAR(500),[CreatedAtUtc] DATETIMEOFFSET NOT NULL,UNIQUE([TenantId],[TransactionNumber]));
INSERT INTO [dbo].[PickupStatuses]([Id],[TenantId],[Code],[Name],[DisplayOrder],[Color],[IsCompleted],[IsActive]) SELECT NEWID(),[Id],v.Code,v.Name,v.Ord,v.Color,v.Done,1 FROM [dbo].[Tenants] CROSS APPLY(VALUES('PLANNED','Planned',10,'blue',0),('CONFIRMED','Customer Confirmed',20,'cyan',0),('PACKING','Packing',30,'orange',0),('PICKED_UP','Picked Up',40,'green',1))v(Code,Name,Ord,Color,Done);
COMMIT;
